QUERY_TEXT:
/* cppi::516fd7f89c1542200f95a2f4c1f5dfc4f021ed3d7c3e94f6d6d968f08176b882 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-05-02' and end_date = '2025-05-02')
and start_date = '2025-05-02' and end_date = '2025-05-02'

/* cppi::97eec93bbce95bc3d4c9af242e8df15d32fc07a23503a37fbe0c3613a1dffe20 */
/* QuickSight dd834227-ee64-478a-ac73-487f6a0600d9 */
SELECT "link", "title", "description", CAST(PARSE_DATETIME("date", 'YYYY-MM-dd''T''HH:mm:ss''Z''') AS TIMESTAMP) AS "date", "service", "category", "year", "month", "day"
FROM "AwsDataCatalog"."optimization_data"."aws_feeds_whats_new"

/* cppi::1ad2ce28f548354c3fd587702fc4bb58d690f5fc842034d26f859070ed0f4f8e */
/* QuickSight 0d913ef9-2a89-4bda-93ed-2b99ef5129fa */
SELECT "business_date", "year", "from_currency", "to_currency", "rate_type_code", "source", "bid_price", "ask_price", "mid_price", "factor", "inverse_quoted", "last_update_date", "vendor_file_name", "arrival_time"
FROM (SELECT *
FROM market.refinitiv_exchange_rates_wmr) AS "FX Rates - EUR, GBP, USD (PROD)"

/* cppi::5ac31157be0f2476440bb0631bd55041afa8e6826c32896b984ba264d01b9483 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-29' and end_date = '2025-04-29')
and start_date = '2025-04-29' and end_date = '2025-04-29'

